    const float g1pbapnua = gmoi_blend(tmp);
    tmp = __fdiv_rn(1.0f + nub, mub);
    const float g1pnub = gmoi_blend(tmp);
    tmp = __fdiv_rn(2.0f + nub, mub);   // (2 + nub): integer 2 promoted
    const float g2pnub = gmoi_blend(tmp);
