            * ((da0lh * ipow2(xdia[LH][2])
                + (tab.dab1[LH][LR] * xdia[LH][2]) * xdia[LR][2])
               + da1lr * ipow2(xdia[LR][2]));
        qhacr = fminf(qhacr, qxmxd[LR]);
        qhacrmlr = qhacr;
        if (temg > TFR) {
