            + (0.04f * vtxbar[LHL][0]) * vtxbar[LI][0]);
        qhlaci0 = ((((pi25 * ehliclsn) * cx[LHL]) * qx[LI]) * vt)
            * ((da0lhl * ipow2(xdia[LHL][2])
                + (tab.dab1[LHL][LI] * xdia[LHL][2]) * xdia[LI][2])
               + tab.da1[LI] * ipow2(xdia[LI][2]));
