            + (0.04f * vtxbar[LH][0]) * vtxbar[LS][0]);
        chacs0 = ((((pi25 * ehsclsn) * cx[LH]) * cx[LS]) * vt)
            * ((da0lh * ipow2(xdia[LH][2])
                + (tab.dab0[LH][LS] * xdia[LH][2]) * xdia[LS][2])
               + tab.da0[LS] * ipow2(xdia[LS][2]));
        chacs = fminf(ehs * chacs0, csmxd);
