    float chlacw = 0.0f;
    if (lhl > 1) {
        if (qhlacw > 0.0f && xmas[LC] > 0.0f) {
            chlacw = __fdiv_rn(qhlacw * rho0, xmascw);
            chlacw = fminf(chlacw, (0.5f * cx[LC]) * dtpinv);
        } else {
