            + (0.04f * vtxbar[LHL][0]) * vtxbar[LS][0]);
        chlacs0 = ((((pi25 * ehlsclsn) * cx[LHL]) * cx[LS]) * vt)
            * ((da0lhl * ipow2(xdia[LHL][2])
                + (tab.dab0[LHL][LS] * xdia[LHL][2]) * xdia[LS][2])
