    // ---- :17329-17483 autoconversion (dmrauto = 0) ----------------------
    float qrcnw = 0.0f, crcnw = 0.0f;
    double cautn = 0.0;
    if (qx[LC] > species(LC).qxmin && cx[LC] > 1000.0f && temg > TFRH + 4.0f) {
